Levítico 1 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"De onde o Senhor falou com Moisés?","o":["Do monte Sinai","Da Tenda da Congregação","De uma sarça ardente","Do meio de uma nuvem"],"c":1,"v":1,"e":"O versículo 1 diz que o Senhor chamou Moisés e falou com ele da Tenda da Congregação."},
 {"t":"multipla","p":"Como devia ser o animal de gado oferecido em holocausto?","o":["Um macho sem defeito","Uma fêmea sem defeito","Um macho de qualquer idade, mesmo com defeito","Qualquer animal do rebanho"],"c":0,"v":3,"e":"O versículo 3 manda trazer um macho sem defeito à porta da tenda da congregação."},
 {"t":"multipla","p":"Onde o ofertante punha a mão para que o holocausto fosse aceito em seu favor?","o":["Sobre o altar","Sobre o sacerdote","Sobre a cabeça do animal","Sobre a porta da tenda"],"c":2,"v":4,"e":"O versículo 4 diz que ele porá a mão sobre a cabeça do holocausto, e este será aceito para a sua expiação."},
 {"t":"multipla","p":"Quem aspergia o sangue do novilho ao redor do altar?","o":["Moisés","O próprio ofertante","Os levitas","Os filhos de Arão, os sacerdotes"],"c":3,"v":5,"e":"O versículo 5 diz que os filhos de Arão, os sacerdotes, apresentarão o sangue e o aspergirão ao redor do altar."},
 {"t":"multipla","p":"O que era lavado com água antes de ser queimado no altar?","o":["A cabeça e a gordura","As entranhas e as pernas","A pele do animal","A lenha do altar"],"c":1,"v":9,"e":"O versículo 9 diz que as entranhas e as pernas serão lavadas com água antes de o sacerdote queimar tudo."},
 {"t":"cv","p":"O carneiro ou o cabrito oferecido em holocausto era degolado ao lado do altar, na parte norte.","c":true,"v":11,"e":"O versículo 11 diz que o animal seria degolado ao lado do altar, na parte norte diante do Senhor."},
 {"t":"cv","p":"O papo e as penas da ave eram queimados sobre o altar junto com ela.","c":false,"v":16,"e":"O versículo 16 diz que o papo com as penas era lançado junto ao altar, para o lado oriental, no local das cinzas."},
 {"t":"cv","p":"O sacerdote rasgava a ave pelas asas, mas não a partia.","c":true,"v":17,"e":"O versículo 17 diz que o sacerdote a rasgará pelas asas, porém não a partirá, e então a queimará sobre o altar."}
]}

Levítico 7 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Onde deve ser imolada a oferta pela culpa?","o":["No lugar onde se oferece o holocausto","Na entrada do acampamento","Fora do arraial","Dentro do lugar santíssimo"],"c":0,"v":2,"e":"O versículo 2 diz que a oferta pela culpa será imolada no lugar onde se oferece o holocausto."},
 {"t":"multipla","p":"Com o que fica o sacerdote que oferece o holocausto de alguém?","o":["A coxa direita","A pele do holocausto","A gordura dos rins","O peito do animal"],"c":1,"v":8,"e":"O versículo 8 diz que o sacerdote fica com a pele do holocausto que apresentou."},
 {"t":"multipla","p":"Quando deve ser comida a carne do sacrifício de ação de graças?","o":["Até o terceiro dia","No dia seguinte ao oferecimento","No dia do seu oferecimento","Somente no sábado"],"c":2,"v":15,"e":"O versículo 15 manda comê-la no dia do oferecimento, sem deixar nada até a manhã."},
 {"t":"multipla","p":"O que se faz com a carne de voto ou oferta voluntária que restar no terceiro dia?","o":["É comida pelos sacerdotes","É guardada no santuário","É dada ao povo","É queimada"],"c":3,"v":17,"e":"O versículo 17 diz que o que restar da carne no terceiro dia será queimado."},
 {"t":"multipla","p":"Que porção recebe o filho de Arão que oferece o sangue e a gordura do sacrifício pacífico?","o":["A pele do animal","A coxa direita","A cauda","Os rins"],"c":1,"v":33,"e":"O versículo 33 diz que esse sacerdote receberá a coxa direita como sua porção."},
 {"t":"cv","p":"Quem estiver limpo pode comer da carne do sacrifício.","c":true,"v":19,"e":"O versículo 19 diz que aquele que estiver limpo poderá comer da carne do sacrifício."},
 {"t":"cv","p":"Era permitido comer sangue de aves, mas não de gado.","c":false,"v":26,"e":"O versículo 26 proíbe comer sangue tanto de aves quanto de gado."},
 {"t":"cv","p":"O Senhor deu essas leis a Moisés no monte Sinai.","c":true,"v":38,"e":"O versículo 38 diz que o Senhor as ordenou a Moisés no monte Sinai."}
]}

Levítico 18 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"O Senhor proibiu Israel de seguir as práticas de quais terras?","o":["Egito e Canaã","Babilônia e Assíria","Moabe e Edom","Egito e Babilônia"],"c":0,"v":3,"e":"No versículo 3, Deus manda não fazer segundo as práticas da terra do Egito nem da terra de Canaã."},
 {"t":"multipla","p":"Segundo o capítulo, o que acontece com o homem que cumpre os estatutos e juízos do Senhor?","o":["Receberá muitas terras","Viverá por meio deles","Terá muitos filhos","Será sacerdote"],"c":1,"v":5,"e":"O versículo 5 diz que, ao cumpri-los, o homem viverá por meio deles."},
 {"t":"multipla","p":"Que razão o texto dá para não descobrir a nudez da nora?","o":["Ela é estrangeira","Ela é mais nova","Ela é mulher de teu filho","Ela pertence a outra tribo"],"c":2,"v":15,"e":"O versículo 15 explica que a nora não deve ser tocada porque ela é mulher de teu filho."},
 {"t":"multipla","p":"A qual deus estrangeiro o povo não devia permitir que sua descendência fosse oferecida?","o":["Baal","Dagom","Moloque","Astarote"],"c":2,"v":21,"e":"O versículo 21 proíbe permitir que a descendência seja oferecida a Moloque."},
 {"t":"multipla","p":"Por causa da contaminação, o que o texto diz que a terra faria com seus moradores?","o":["Deixaria de dar fruto","Seria entregue a outro povo","Ficaria deserta para sempre","Expulsaria os seus moradores"],"c":3,"v":25,"e":"O versículo 25 diz que a terra expulsará os seus moradores."},
 {"t":"cv","p":"O capítulo chama a mulher do irmão do pai de tia.","c":true,"v":14,"e":"O versículo 14 diz para não se aproximar da mulher do irmão do pai, pois ela é tua tia."},
 {"t":"cv","p":"Essas leis valiam só para os nativos de Israel, e não para o estrangeiro que peregrinava entre eles.","c":false,"v":26,"e":"O versículo 26 diz que nem o nativo nem o estrangeiro que peregrina entre eles deviam fazer essas abominações."},
 {"t":"cv","p":"Quem praticasse alguma dessas abominações seria eliminado do seu povo.","c":true,"v":29,"e":"O versículo 29 diz que aqueles que as praticarem serão eliminados do seu povo."}
]}

Levítico 23 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"O que o capítulo determina para o sétimo dia da semana?","o":["Sábado de descanso, sem nenhuma obra","Dia de colher as primícias","Dia de habitar em tendas","Dia de tocar as trombetas"],"c":0,"v":3,"e":"O versículo 3 diz que se trabalha seis dias e que o sétimo é sábado de descanso, sem nenhuma obra."},
 {"t":"multipla","p":"Quando é a Páscoa do Senhor?","o":["No primeiro mês, no dia catorze, ao crepúsculo da tarde","No primeiro mês, no dia quinze, pela manhã","No sétimo mês, no dia dez","No sétimo mês, no dia quinze"],"c":0,"v":5,"e":"O versículo 5 marca a Páscoa no primeiro mês, no décimo quarto dia, ao crepúsculo da tarde."},
 {"t":"multipla","p":"Ao entrar na terra e colher a messe, o que os israelitas deviam levar ao sacerdote?","o":["Um molho das primícias da colheita","Um décimo de toda a colheita","Dois pães asmos","Um bode para expiação"],"c":0,"v":10,"e":"O versículo 10 manda trazer ao sacerdote um molho das primícias da colheita."},
 {"t":"multipla","p":"Como deviam ser feitos os dois pães de oferta movida trazidos após os cinquenta dias?","o":["Levedados","Asmos, sem fermento","Assados com mel","Misturados com incenso"],"c":0,"v":17,"e":"O versículo 17 diz que os dois pães se cozeriam levedados, como primícias ao Senhor."},
 {"t":"multipla","p":"Na colheita, o que deveria ser deixado para o pobre e para o estrangeiro?","o":["Os cantos do campo e as espigas caídas","A primeira parte de toda a colheita","Os grãos tostados","Os dois pães das primícias"],"c":0,"v":22,"e":"O versículo 22 manda não rebuscar os cantos do campo nem colher as espigas caídas, deixando-as para o pobre e o estrangeiro."},
 {"t":"cv","p":"No primeiro dia do sétimo mês haveria um dia de descanso solene, memorial com sons de trombetas.","c":true,"v":24,"e":"O versículo 24 descreve esse dia como descanso solene, memorial com sons de trombetas e santa convocação."},
 {"t":"cv","p":"No Dia da Expiação era permitido trabalhar depois de apresentar a oferta queimada.","c":false,"v":28,"e":"O versículo 28 diz que nesse mesmo dia não se faria nenhuma obra, porque é o dia da expiação."},
 {"t":"cv","p":"Na festa dos tabernáculos, Israel habitaria em tendas para lembrar que Deus os fez habitar em tendas quando os tirou do Egito.","c":true,"v":43,"e":"O versículo 43 explica que as tendas servem para que as gerações saibam que Deus fez Israel habitar em tendas ao tirá-lo do Egito."}
]}

Levítico 13 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"A quem devia ser levado o homem com inchação, pústula ou mancha lustrosa na pele?","o":["A Arão, o sacerdote, ou a um de seus filhos","A Moisés","Aos anciãos do povo","Aos chefes das tribos"],"c":0,"v":2,"e":"O versículo 2 diz que ele seria levado a Arão, o sacerdote, ou a um de seus filhos, sacerdotes."},
 {"t":"multipla","p":"Se a mancha não parecia mais profunda que a pele e os pelos não tinham ficado brancos, o que o sacerdote fazia?","o":["Declarava a pessoa imunda na hora","Isolava a pessoa por sete dias","Mandava lavar as vestes e a liberava","Mandava a pessoa para fora do acampamento"],"c":1,"v":4,"e":"O versículo 4 diz que, nesse caso, o sacerdote isolava o portador da praga por sete dias."},
 {"t":"multipla","p":"Se a lepra cobrisse toda a pele, da cabeça aos pés, e ficasse branca, o que o sacerdote fazia?","o":["Declarava a pessoa imunda","Isolava a pessoa por sete dias","Mandava a pessoa para fora do acampamento","Declarava a pessoa limpa"],"c":3,"v":13,"e":"O versículo 13 diz que, se a lepra cobrisse toda a carne e se tornasse branca, o sacerdote declarava a pessoa limpa."},
 {"t":"multipla","p":"Na queimadura em que o pelo ficou branco e a ferida parecia mais funda que a pele, o que era?","o":["Cicatriz da queimadura","Impigem branca","Lepra que surgiu da queimadura","Úlcera já sarada"],"c":2,"v":25,"e":"O versículo 25 diz que é lepra que surgiu da queimadura, e o sacerdote a declarava imunda."},
 {"t":"multipla","p":"Na praga da cabeça ou da barba que não se espalhou em sete dias, o que se fazia antes do segundo isolamento?","o":["Rapava-se só a mancha","Ungia-se a cabeça com azeite","Declarava-se a pessoa imunda","O homem era rapado, mas a mancha não"],"c":3,"v":33,"e":"O versículo 33 diz que o homem seria rapado, mas não se raparia a mancha, e ficaria isolado por mais sete dias."},
 {"t":"cv","p":"Enquanto a praga estivesse nele, o leproso devia morar dentro do acampamento.","c":false,"v":46,"e":"O versículo 46 diz que ele habitaria sozinho e que sua morada seria fora do acampamento."},
 {"t":"cv","p":"A veste em que a praga se espalhou depois de sete dias devia ser queimada.","c":true,"v":52,"e":"O versículo 52 diz que a vestimenta com essa praga seria queimada, pois é lepra corrosiva."},
 {"t":"cv","p":"A veste lavada da qual a praga saiu devia ser lavada uma segunda vez e então ficava limpa.","c":true,"v":58,"e":"O versículo 58 diz que essa veste deveria ser lavada uma segunda vez e ficaria limpa."}
]}

Levítico 19 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Por que os filhos de Israel deveriam ser santos?","o":["Porque eram um povo grande","Porque o Senhor, seu Deus, é santo","Porque tinham saído do Egito","Porque guardavam os sábados"],"c":1,"v":2,"e":"No versículo 2, Deus diz: 'Serão santos porque eu, o SENHOR, seu Deus, sou santo'."},
 {"t":"multipla","p":"O que devia ser feito com o que sobrasse do sacrifício pacífico até o terceiro dia?","o":["Ser comido pelos sacerdotes","Ser dado aos pobres","Ser queimado","Ser enterrado fora do arraial"],"c":2,"v":6,"e":"O versículo 6 diz que o que sobrar até o terceiro dia será queimado."},
 {"t":"multipla","p":"Para quem deviam ficar as espigas caídas e os bagos caídos da vinha?","o":["Para o pobre e o estrangeiro","Para os levitas e os sacerdotes","Para a viúva e o órfão","Para o dono do campo vizinho"],"c":0,"v":10,"e":"O versículo 10 manda deixá-los para o pobre e para o estrangeiro."},
 {"t":"multipla","p":"Segundo o capítulo, como cada um deve amar o seu próximo?","o":["Mais do que a si mesmo","Como ama o seu pai e a sua mãe","Como ama a sua terra","Como a si mesmo"],"c":3,"v":18,"e":"O versículo 18 diz: 'amarás o teu próximo como a ti mesmo'."},
 {"t":"multipla","p":"Em que ano o povo poderia comer o fruto das árvores que plantasse na terra?","o":["No terceiro ano","No quinto ano","No quarto ano","No sétimo ano"],"c":1,"v":25,"e":"O fruto ficava vedado por três anos, era oferta ao Senhor no quarto, e no quinto ano o povo o comeria (versículos 23 a 25)."},
 {"t":"cv","p":"Era permitido fazer cortes na carne por causa dos mortos.","c":false,"v":28,"e":"O versículo 28 diz: 'Não fareis cortes na carne em razão dos mortos'."},
 {"t":"cv","p":"O povo devia se levantar diante dos cabelos brancos e honrar a presença do idoso.","c":true,"v":32,"e":"O versículo 32 diz: 'Levanta-te diante dos cabelos brancos e honra a presença do idoso'."},
 {"t":"cv","p":"O estrangeiro devia ser amado porque Israel tinha sido estrangeiro na terra da Babilônia.","c":false,"v":34,"e":"O versículo 34 diz que Israel tinha sido estrangeiro na terra do Egito."}
]}

Levítico 27 Â· exercÃ­cios.texto:
{"perguntas":[
{"t":"multipla","p":"Qual era a avaliação de um homem de vinte a sessenta anos dedicado por voto?","o":["Trinta siclos de prata","Cinquenta siclos de prata","Vinte siclos de prata","Quinze siclos de prata"],"c":1,"v":3,"e":"O versículo 3 fixa a avaliação do homem de vinte a sessenta anos em cinquenta siclos de prata, segundo o siclo do santuário."},
{"t":"multipla","p":"Se quem fez o voto fosse pobre demais para pagar a avaliação, o que acontecia?","o":["Ficava livre do voto","Pagava em parcelas até o Jubileu","O sacerdote o avaliava conforme as suas posses","Um parente pagava por ele"],"c":2,"v":8,"e":"O versículo 8 diz que ele se apresentava ao sacerdote, que o avaliava conforme o que suas posses permitiam."},
{"t":"multipla","p":"Se alguém trocasse o animal oferecido ao Senhor por outro, o que acontecia?","o":["Só o primeiro animal ficava santo","Só o segundo animal ficava santo","A oferta era anulada","Os dois animais ficavam santos"],"c":3,"v":10,"e":"O versículo 10 diz que, se trocasse animal por animal, um e outro seriam santos."},
{"t":"multipla","p":"O que devia fazer quem consagrou a casa e depois quis resgatá-la?","o":["Pagar a avaliação mais um quinto","Esperar o Ano do Jubileu","Oferecer um cordeiro em troca","Pagar o dobro da avaliação"],"c":0,"v":15,"e":"O versículo 15 manda acrescentar um quinto ao valor da avaliação para a casa voltar a ser sua."},
{"t":"multipla","p":"Pelo que se avaliava a parte do campo da herança consagrada ao Senhor?","o":["Pelo número de árvores do campo","Pela semente necessária para semeá-lo","Pela colheita do ano anterior","Pelo tamanho medido em côvados"],"c":1,"v":16,"e":"O versículo 16 diz que a avaliação era segundo a semente necessária para semeá-lo, um homer de cevada valendo cinquenta siclos."},
{"t":"cv","p":"No Ano do Jubileu, o campo comprado e consagrado ao Senhor voltava a quem o vendeu, o dono por herança.","c":true,"v":24,"e":"O versículo 24 diz que no Jubileu o campo retornava a quem o vendeu, a quem pertencia por herança."},
{"t":"cv","p":"Quem resgatasse parte do seu dízimo tinha de pagar o dobro do valor.","c":false,"v":31,"e":"O versículo 31 manda acrescentar um quinto, e não pagar o dobro."},
{"t":"cv","p":"O capítulo termina dizendo que esses mandamentos foram dados a Moisés no monte Sinai.","c":true,"v":34,"e":"O versículo 34 diz que esses são os mandamentos que o Senhor deu a Moisés para os filhos de Israel no monte Sinai."}
]}

Levítico 4 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"O que o sacerdote ungido devia oferecer quando pecasse?","o":["Um bode macho sem defeito","Uma cabra sem defeito","Um novilho sem defeito","Uma cordeira sem defeito"],"c":2,"v":3,"e":"O versículo 3 diz que o sacerdote ungido oferecerá um novilho sem defeito como oferta pelo pecado."},
 {"t":"multipla","p":"Para onde era levado o resto do novilho do sacerdote, com pele, carne e cabeça, para ser queimado?","o":["Para dentro do santuário, diante do véu","Para fora do acampamento, a um lugar limpo onde se lança a cinza","Para o altar do incenso aromático","Para a casa do sacerdote"],"c":1,"v":12,"e":"O versículo 12 diz que o novilho era levado para fora do acampamento, a um lugar limpo onde se lança a cinza, e ali queimado."},
 {"t":"multipla","p":"Quando toda a congregação pecava, quem punha as mãos sobre a cabeça do novilho?","o":["O sacerdote ungido","Moisés","Os anciãos da congregação","Os príncipes das tribos"],"c":2,"v":15,"e":"O versículo 15 diz que os anciãos da congregação punham as mãos sobre a cabeça do novilho diante do SENHOR."},
 {"t":"multipla","p":"O que o príncipe devia trazer como oferta quando seu pecado fosse notificado?","o":["Um bode macho sem defeito","Um novilho sem defeito","Uma cabra sem defeito","Duas rolinhas"],"c":0,"v":23,"e":"O versículo 23 diz que o príncipe trará como oferta um bode macho, sem defeito, do seu rebanho."},
 {"t":"multipla","p":"O que uma pessoa do povo da terra trazia como oferta pelo pecado, segundo o versículo 28?","o":["Um novilho sem defeito","Um bode macho sem defeito","Uma cabra sem defeito","Um carneiro sem defeito"],"c":2,"v":28,"e":"O versículo 28 diz que a pessoa do povo trará como oferta uma cabra sem defeito pelo pecado que cometeu."},
 {"t":"cv","p":"Na oferta da pessoa do povo, o sacerdote levava o sangue para dentro da tenda e o aspergia sete vezes diante do véu.","c":false,"v":30,"e":"O versículo 30 diz que o sacerdote punha o sangue sobre os chifres do altar do holocausto e derramava o restante na base do altar."},
 {"t":"cv","p":"A pessoa do povo também podia trazer uma cordeira, fêmea sem defeito, como oferta pelo pecado.","c":true,"v":32,"e":"O versículo 32 diz que, se trouxesse uma cordeira como oferta pelo pecado, deveria ser uma fêmea sem defeito."},
 {"t":"cv","p":"O capítulo termina dizendo que o sacerdote fará expiação pela pessoa e que o pecado lhe será perdoado.","c":true,"v":35,"e":"O versículo 35 diz que o sacerdote fará expiação por essa pessoa e que o pecado lhe será perdoado."}
]}

Levítico 24 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Que azeite os israelitas deviam trazer para o candelabro?","o":["Azeite de nardo perfumado","Azeite puro de oliveira, batido","Azeite misturado com incenso","Azeite de oliveira cozido"],"c":1,"v":2,"e":"O versículo 2 manda trazer azeite puro de oliveira, batido, para que a lâmpada ficasse acesa continuamente."},
 {"t":"multipla","p":"Como os pães deviam ser arrumados sobre a mesa de ouro?","o":["Em uma pilha só","Em três fileiras de quatro","Em duas fileiras de seis","Em doze cestos separados"],"c":2,"v":6,"e":"O versículo 6 manda colocar os pães em duas fileiras, seis em cada fileira, sobre a mesa de ouro puro."},
 {"t":"multipla","p":"Com que frequência Arão devia dispor os pães diante do Senhor?","o":["A cada sábado","Todas as manhãs","Uma vez por mês","Só no Dia da Expiação"],"c":0,"v":8,"e":"O versículo 8 diz que a cada sábado Arão os disporia diante do Senhor, continuamente."},
 {"t":"multipla","p":"Quem era o pai do homem que blasfemou o nome do Senhor?","o":["Um homem da tribo de Dã","Um sacerdote levita","Um moabita","Um egípcio"],"c":3,"v":10,"e":"O versículo 10 diz que ele era filho de uma mulher israelita e de um egípcio."},
 {"t":"multipla","p":"O que fizeram com o blasfemo logo depois de levá-lo a Moisés?","o":["Apedrejaram-no na mesma hora","Prenderam-no até que o Senhor declarasse o que fazer","Expulsaram-no para o Egito","Mandaram-no oferecer um sacrifício"],"c":1,"v":12,"e":"O versículo 12 diz que o prenderam até receberem a declaração pela boca do Senhor."},
 {"t":"cv","p":"Todos os que ouviram a blasfêmia deviam pôr as mãos sobre a cabeça do blasfemo.","c":true,"v":14,"e":"O versículo 14 manda que todos os que o ouviram ponham as mãos sobre a cabeça dele."},
 {"t":"cv","p":"Quem matasse um animal deveria ser morto, assim como quem matasse um homem.","c":false,"v":21,"e":"O versículo 21 diz que quem matar um animal deve restituí-lo, e só quem matar um homem será morto."},
 {"t":"cv","p":"Os filhos de Israel levaram o blasfemo para fora do acampamento e o apedrejaram, como o Senhor havia ordenado a Moisés.","c":true,"v":23,"e":"O versículo 23 conta que eles o apedrejaram fora do acampamento e fizeram como o Senhor havia ordenado a Moisés."}
]}

Levítico 16 Â· exercÃ­cios.texto:
{"perguntas":[
{"t":"multipla","p":"Quando o Senhor falou a Moisés as instruções deste capítulo?","o":["Depois que o povo fez o bezerro de ouro","Depois que Arão foi ungido sacerdote","Depois que morreram os dois filhos de Arão","Depois que o tabernáculo foi levantado"],"c":2,"v":1,"e":"O versículo 1 diz que o Senhor falou a Moisés depois que morreram os dois filhos de Arão."},
{"t":"multipla","p":"De que eram feitas as vestes sagradas que Arão devia usar?","o":["Linho","Lã tingida","Pelo de cabra","Fios de ouro"],"c":0,"v":4,"e":"O versículo 4 descreve a túnica, as calças, o cinto e a mitra, todos de linho."},
{"t":"multipla","p":"Como Arão definia qual bode seria para o Senhor e qual iria para o deserto?","o":["Escolhia o bode maior para o Senhor","Lançava sortes sobre os dois","Perguntava a Moisés","Deixava o povo escolher"],"c":1,"v":8,"e":"O versículo 8 diz que Arão lançava sortes sobre os dois bodes, uma para o Senhor e outra para o bode enviado ao deserto."},
{"t":"multipla","p":"Para que Arão colocava incenso sobre o fogo diante do Senhor?","o":["Para perfumar a tenda da congregação","Para chamar o povo à reunião","Para purificar as vestes de linho","Para que a nuvem cobrisse o propiciatório e ele não morresse"],"c":3,"v":13,"e":"O versículo 13 diz que a nuvem do incenso devia cobrir o propiciatório, a fim de que Arão não morresse."},
{"t":"multipla","p":"O que Arão fazia com o bode vivo antes de enviá-lo ao deserto?","o":["Aspergia sangue sobre ele sete vezes","Ungia sua cabeça com azeite","Punha as duas mãos sobre sua cabeça e confessava os pecados de Israel","Amarrava nele um pano de linho"],"c":2,"v":21,"e":"O versículo 21 diz que Arão colocava ambas as mãos sobre a cabeça do bode vivo e confessava sobre ele as iniquidades dos filhos de Israel."},
{"t":"cv","p":"Quem levava o bode expiatório ao deserto devia lavar as vestes e banhar o corpo antes de entrar de novo no acampamento.","c":true,"v":26,"e":"O versículo 26 manda que esse homem lave as vestes e banhe o corpo em água, e só depois entre no acampamento."},
{"t":"cv","p":"O dia da expiação devia ser guardado no primeiro mês, aos dez dias do mês.","c":false,"v":29,"e":"O versículo 29 diz que era no sétimo mês, aos dez dias do mês."},
{"t":"cv","p":"Essa expiação pelos pecados dos filhos de Israel devia ser feita uma vez por ano.","c":true,"v":34,"e":"O versículo 34 diz que o estatuto perpétuo era fazer expiação pelos filhos de Israel uma vez por ano."}
]}

Levítico 20 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Quem deveria apedrejar quem entregasse os filhos a Moloque?","o":["Os sacerdotes","O povo da terra","Moisés","Os levitas"],"c":1,"v":2,"e":"No versículo 2 está escrito que \"o povo da terra o apedrejará\"."},
 {"t":"multipla","p":"Segundo Deus, o que o homem contamina ao oferecer seus filhos a Moloque?","o":["O altar","O acampamento","O santuário","A terra"],"c":2,"v":3,"e":"No versículo 3, Deus diz que esse homem contamina \"o meu santuário\" e profana o seu santo nome."},
 {"t":"multipla","p":"Contra quem Deus diz que vai se voltar no versículo 6?","o":["Quem buscar adivinhadores e feiticeiros","Quem comer animais imundos","Quem trabalhar no sábado","Quem não oferecer sacrifícios"],"c":0,"v":6,"e":"No versículo 6, Deus diz que se voltará contra quem se voltar para os adivinhadores e feiticeiros."},
 {"t":"multipla","p":"Qual é a punição para quem amaldiçoar o pai ou a mãe?","o":["Pagar uma multa","Oferecer um sacrifício","Ser expulso do acampamento","Ser punido com a morte"],"c":3,"v":9,"e":"No versículo 9 está escrito que quem amaldiçoar o pai ou a mãe certamente será punido com a morte."},
 {"t":"multipla","p":"Por que o povo deve guardar os estatutos e os juízos de Deus?","o":["Para ser mais numeroso que as nações","Para que a terra não os rejeite","Para receber sacerdotes","Para vencer o Egito"],"c":1,"v":22,"e":"No versículo 22, Deus manda cumprir seus estatutos para que a terra para onde os leva não os rejeite."},
 {"t":"cv","p":"No caso do homem que toma uma mulher e também a mãe dela, o capítulo manda apedrejar os três.","c":false,"v":14,"e":"O versículo 14 diz que a ele e a elas \"queimarão\", e não que serão apedrejados."},
 {"t":"cv","p":"Deus diz que as nações que ele expulsa praticaram todas essas coisas e que por isso se aborreceu delas.","c":true,"v":23,"e":"No versículo 23, Deus diz que essas nações praticaram todas essas coisas e que por isso se aborreceu delas."},
 {"t":"cv","p":"O capítulo termina dizendo que o homem ou a mulher que forem necromantes ou feiticeiros serão apedrejados.","c":true,"v":27,"e":"No versículo 27 está escrito que necromantes ou feiticeiros certamente serão mortos e apedrejados."}
]}

Levítico 17 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Onde o israelita devia levar o boi, o cordeiro ou a cabra que fosse sacrificar?","o":["À porta da tenda da congregação","Ao lugar onde o animal foi morto","À casa de Arão","Para fora do acampamento"],"c":0,"v":4,"e":"O versículo 4 manda trazer o animal à porta da tenda da congregação como oferta ao Senhor."},
 {"t":"multipla","p":"O que o sacerdote devia fazer com o sangue desses sacrifícios?","o":["Derramá-lo no chão e cobri-lo com pó","Aspergi-lo sobre o altar do Senhor","Levá-lo para fora do acampamento","Passá-lo nas portas das tendas"],"c":1,"v":6,"e":"O versículo 6 diz que o sacerdote aspergirá o sangue sobre o altar do Senhor e queimará a gordura."},
 {"t":"multipla","p":"A quem os israelitas nunca mais deviam oferecer seus sacrifícios?","o":["Aos reis de Canaã","Ao sol e à lua","Aos demônios","Aos estrangeiros"],"c":2,"v":7,"e":"O versículo 7 diz que nunca mais oferecerão seus sacrifícios aos demônios."},
 {"t":"multipla","p":"Que razão o capítulo dá para não se comer sangue?","o":["Porque o sangue é imundo até o anoitecer","Porque o sangue pertence ao sacerdote","Porque o sangue deve ser guardado para a Páscoa","Porque a vida da carne está no sangue"],"c":3,"v":11,"e":"O versículo 11 explica que a vida da carne está no sangue e que é o sangue que faz expiação."},
 {"t":"multipla","p":"O que devia fazer quem caçasse um animal ou uma ave que se come?","o":["Derramar o sangue e cobri-lo com pó","Levar o animal ao sacerdote","Queimar o sangue no altar","Lavar o animal em água"],"c":0,"v":13,"e":"O versículo 13 manda o caçador derramar o sangue e cobri-lo com pó."},
 {"t":"cv","p":"Deus diz que voltará a sua face contra quem comer sangue, seja israelita ou estrangeiro que habita entre eles.","c":true,"v":10,"e":"O versículo 10 afirma que Deus voltará a sua face contra essa pessoa e a eliminará do seu povo."},
 {"t":"cv","p":"Quem comer carne de animal que morreu por si fica imundo por sete dias.","c":false,"v":15,"e":"O versículo 15 diz que a pessoa lava as vestes, banha-se e fica imunda até o anoitecer."},
 {"t":"cv","p":"Quem não lavar as vestes nem banhar o corpo levará sobre si a sua iniquidade.","c":true,"v":16,"e":"O versículo 16 diz que, se não lavar nem se banhar, levará sobre si a sua iniquidade."}
]}

Levítico 2 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"De que deve ser feita a oferta de manjares?","o":["De flor de farinha","De grãos de cevada","De carne de cordeiro","De frutas secas"],"c":0,"v":1,"e":"O versículo 1 diz que a oferta de manjares será de flor de farinha, com azeite e incenso."},
 {"t":"multipla","p":"A quem o ofertante leva a oferta de manjares?","o":["Aos anciãos do povo","Aos filhos de Arão, os sacerdotes","Aos levitas cantores","Ao próprio Moisés"],"c":1,"v":2,"e":"O versículo 2 diz que a oferta é levada aos filhos de Arão, os sacerdotes."},
 {"t":"multipla","p":"Como deve ser a oferta de manjares cozida no forno?","o":["Bolos com fermento e mel","Pães temperados com vinho","Bolos asmos amassados com azeite e obreias asmas untadas com azeite","Massa frita em gordura"],"c":2,"v":4,"e":"O versículo 4 descreve a oferta do forno como bolos asmos amassados com azeite e obreias asmas untadas com azeite."},
 {"t":"multipla","p":"Depois que a oferta é apresentada ao sacerdote, quem a leva ao altar?","o":["O próprio ofertante","Um levita","O sacerdote","Moisés"],"c":2,"v":8,"e":"O versículo 8 diz que a oferta é apresentada ao sacerdote, que a leva ao altar."},
 {"t":"multipla","p":"O que não pode haver em nenhuma oferta queimada ao Senhor?","o":["Sal ou azeite","Fermento ou mel","Incenso ou farinha","Trigo ou espigas"],"c":1,"v":11,"e":"O versículo 11 diz que não se queimará ao Senhor oferta que contenha fermento ou mel."},
 {"t":"cv","p":"As primícias podiam ser apresentadas ao Senhor, mas não eram colocadas sobre o altar como aroma agradável.","c":true,"v":12,"e":"O versículo 12 diz que as primícias são apresentadas ao Senhor, mas não são colocadas sobre o altar como aroma agradável."},
 {"t":"cv","p":"Na oferta de manjares, o sal podia ser deixado de fora.","c":false,"v":13,"e":"O versículo 13 manda não deixar faltar o sal da aliança e aplicar sal em todas as ofertas."},
 {"t":"cv","p":"A oferta de manjares das primícias era feita de espigas verdes tostadas ao fogo.","c":true,"v":14,"e":"O versículo 14 diz que a oferta das primícias é de espigas verdes tostadas ao fogo, de grãos esmagados."}
]}

Levítico 8 Â· exercÃ­cios.texto:
{"perguntas":[
{"t":"multipla","p":"O que Moisés fez com Arão e seus filhos antes de vesti-los?","o":["Ungiu-os com óleo","Lavou-os com água","Aspergiu sangue sobre eles","Impôs as mãos sobre eles"],"c":1,"v":6,"e":"No versículo 6, Moisés trouxe Arão e seus filhos e os lavou com água."},
{"t":"multipla","p":"O que Moisés colocou no peitoral de Arão?","o":["A lâmina de ouro","O cinto do éfode","O Urim e o Tumim","O óleo da unção"],"c":2,"v":8,"e":"O versículo 8 diz que Moisés colocou o peitoral e pôs nele o Urim e o Tumim."},
{"t":"multipla","p":"Onde foram queimados a pele, a carne e o excremento do novilho da oferta pelo pecado?","o":["Sobre o altar","À porta da tenda","Dentro do tabernáculo","Fora do acampamento"],"c":3,"v":17,"e":"O versículo 17 diz que o novilho, com pele, carne e excremento, foi queimado fora do acampamento."},
{"t":"multipla","p":"Onde Moisés pôs o sangue do carneiro da consagração em Arão?","o":["Na orelha direita, no polegar da mão direita e no do pé direito","Na testa e nas duas mãos","Sobre a mitra e o peitoral","Nos ombros e no peito"],"c":0,"v":23,"e":"No versículo 23, Moisés pôs o sangue na ponta da orelha direita de Arão, no polegar da mão direita e no polegar do pé direito."},
{"t":"multipla","p":"Que parte do carneiro da consagração coube a Moisés?","o":["A coxa direita","A cabeça","O peito","A cauda"],"c":2,"v":29,"e":"O versículo 29 diz que o peito, apresentado como oferta movida, era a porção que cabia a Moisés."},
{"t":"cv","p":"Moisés aspergiu óleo da unção e sangue do altar sobre Arão, seus filhos e as vestes deles.","c":true,"v":30,"e":"O versículo 30 diz que Moisés aspergiu o óleo e o sangue sobre Arão, seus filhos e as vestes de todos."},
{"t":"cv","p":"A carne e o pão que sobrassem deviam ser guardados para o dia seguinte.","c":false,"v":32,"e":"O versículo 32 manda queimar o que restasse da carne e do pão."},
{"t":"cv","p":"Arão e seus filhos deviam ficar à porta da tenda da congregação, dia e noite, por sete dias.","c":true,"v":35,"e":"O versículo 35 ordena que eles ficassem à porta da tenda, dia e noite, por sete dias."}
]}

Levítico 5 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"O que acontece com quem foi testemunha, viu ou soube do ocorrido e não o revelou?","o":["Será expulso do arraial","Pagará o dobro ao prejudicado","Levará sobre si sua iniquidade","Ficará impuro até a tarde"],"c":2,"v":1,"e":"O versículo 1 diz que quem não revelar o que viu ou soube levará sobre si sua iniquidade."},
 {"t":"multipla","p":"Quem se tornava culpado numa dessas situações devia primeiro:","o":["Jejuar sete dias","Confessar o que cometeu","Lavar as vestes","Sair do arraial"],"c":1,"v":5,"e":"O versículo 5 manda que o culpado confesse o que cometeu."},
 {"t":"multipla","p":"Que animal do gado miúdo a pessoa trazia como oferta pelo pecado?","o":["Uma cordeira ou uma cabra","Um novilho sem defeito","Um touro ou um bode","Um bezerro do rebanho"],"c":0,"v":6,"e":"O versículo 6 diz que a oferta era uma cordeira ou uma cabra do gado miúdo."},
 {"t":"multipla","p":"Quem não tinha condições de trazer um cordeiro oferecia:","o":["Um cabrito pequeno","Um efa de cevada","Dois carneiros","Duas rolas ou dois pombinhos"],"c":3,"v":7,"e":"O versículo 7 diz que, sem condições para um cordeiro, a pessoa oferecia duas rolas ou dois pombinhos."},
 {"t":"multipla","p":"Como devia ser a oferta de flor de farinha de quem não podia trazer as aves?","o":["Com azeite, mas sem incenso","Sem azeite e sem incenso","Misturada com mel","Com sal e fermento"],"c":1,"v":11,"e":"O versículo 11 diz que não se devia deitar azeite nem pôr incenso, por ser oferta pelo pecado."},
 {"t":"cv","p":"O que sobrava da oferta de farinha ficava para o sacerdote.","c":true,"v":13,"e":"O versículo 13 diz que o que sobrar será do sacerdote, como a oferta de manjares."},
 {"t":"cv","p":"Quem pecou nas coisas sagradas do SENHOR devia restituir o dobro do valor.","c":false,"v":16,"e":"O versículo 16 manda restituir e acrescentar um quinto do valor, não o dobro."},
 {"t":"cv","p":"Quem transgride um mandamento do Senhor, mesmo sem saber, é culpado.","c":true,"v":17,"e":"O versículo 17 diz que, mesmo que não o saiba, ainda assim será culpado."}
]}

Levítico 12 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Com quem o Senhor falou no início do capítulo?","o":["Arão","Moisés","Josué","Os sacerdotes"],"c":1,"v":1,"e":"O versículo 1 diz que o Senhor falou a Moisés."},
 {"t":"multipla","p":"O que deve ser feito com o menino no oitavo dia?","o":["Ele deve ser circuncidado","Ele deve ser levado ao santuário","Ele deve receber o nome","Ele deve ser apresentado ao sacerdote"],"c":0,"v":3,"e":"O versículo 3 manda circuncidar o menino no oitavo dia."},
 {"t":"multipla","p":"Enquanto não terminam os dias de sua purificação, o que a mulher não pode fazer?","o":["Sair de casa","Preparar alimento","Tocar em coisa santa nem entrar no santuário","Falar com o sacerdote"],"c":2,"v":4,"e":"O versículo 4 diz que ela não tocará em coisa santa nem entrará no santuário."},
 {"t":"multipla","p":"Quando a mulher dá à luz uma menina, por quanto tempo fica imunda?","o":["Sete dias","Trinta e três dias","Sessenta e seis dias","Duas semanas"],"c":3,"v":5,"e":"O versículo 5 diz que, por uma menina, ela fica imunda durante duas semanas."},
 {"t":"multipla","p":"O que a mulher leva ao sacerdote como holocausto ao fim da purificação?","o":["Um bezerro","Um cordeiro de um ano","Um carneiro","Um bode"],"c":1,"v":6,"e":"O versículo 6 diz que ela traz um cordeiro de um ano como holocausto."},
 {"t":"cv","p":"A mulher leva suas ofertas ao sacerdote diante da porta da tenda da congregação.","c":true,"v":6,"e":"O versículo 6 diz que ela traz as ofertas diante da porta da tenda da congregação."},
 {"t":"cv","p":"Esta lei vale somente para a mulher que dá à luz um menino.","c":false,"v":7,"e":"O versículo 7 diz que esta é a lei da mulher que der à luz um filho ou uma filha."},
 {"t":"cv","p":"Se a mulher não tiver condição de trazer um cordeiro, ela fica dispensada de qualquer oferta.","c":false,"v":8,"e":"O versículo 8 diz que, nesse caso, ela traz duas rolas ou dois pombinhos."}
]}

Levítico 9 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Em que dia Moisés chamou Arão, seus filhos e os anciãos de Israel?","o":["No sétimo dia","No oitavo dia","No primeiro dia","No décimo dia"],"c":1,"v":1,"e":"O versículo 1 diz que foi no oitavo dia que Moisés chamou Arão, seus filhos e os anciãos."},
 {"t":"multipla","p":"Que animal Arão devia tomar para a sua oferta pelo pecado?","o":["Um bezerro","Um bode","Um cordeiro","Um boi"],"c":0,"v":2,"e":"No versículo 2, Moisés manda Arão tomar um bezerro para oferta pelo pecado e um carneiro para holocausto."},
 {"t":"multipla","p":"Que motivo Moisés deu para o povo trazer as ofertas naquele dia?","o":["Era dia de festa da colheita","O povo tinha murmurado contra Arão","Naquele dia o Senhor lhes apareceria","Arão ia ser ungido sacerdote"],"c":2,"v":4,"e":"O versículo 4 termina dizendo: \"pois hoje o Senhor lhes aparecerá\"."},
 {"t":"multipla","p":"O que foi feito com a carne e a pele da oferta pelo pecado de Arão?","o":["Foram queimadas sobre o altar","Foram comidas pelos filhos de Arão","Foram dadas aos anciãos","Foram queimadas fora do acampamento"],"c":3,"v":11,"e":"O versículo 11 diz que a carne e a pele foram queimadas fora do acampamento."},
 {"t":"multipla","p":"O que Arão moveu como oferta movida perante o Senhor?","o":["A cabeça e as pernas","O peito e a coxa direita","A gordura e os rins","A cauda e o fígado"],"c":1,"v":21,"e":"O versículo 21 diz que Arão moveu o peito e a coxa direita como oferta movida, conforme Moisés havia ordenado."},
 {"t":"cv","p":"Os filhos de Arão trouxeram-lhe o sangue do bezerro, e ele o pôs com o dedo sobre os chifres do altar.","c":true,"v":9,"e":"O versículo 9 diz que os filhos de Arão lhe trouxeram o sangue e ele o colocou com o dedo sobre os chifres do altar."},
 {"t":"cv","p":"Arão apresentou a oferta do povo antes de fazer a sua própria oferta pelo pecado.","c":false,"v":15,"e":"Arão primeiro sacrificou o bezerro por si (versículo 8) e só depois apresentou a oferta do povo (versículo 15)."},
 {"t":"cv","p":"O fogo que consumiu o holocausto e a gordura sobre o altar saiu da presença do Senhor.","c":true,"v":24,"e":"O versículo 24 diz que o fogo saiu da presença do Senhor e consumiu o holocausto e a gordura sobre o altar."}
]}

Levítico 6 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Além de restituir por inteiro o que tomou, o que o culpado devia acrescentar?","o":["A quinta parte","A décima parte","O dobro do valor","A metade do valor"],"c":0,"v":5,"e":"No versículo 5, o culpado restitui por inteiro e acrescenta a quinta parte a quem pertence."},
 {"t":"multipla","p":"Que animal o culpado trazia ao Senhor como oferta pela culpa?","o":["Um bode do rebanho","Um carneiro sem defeito","Um novilho sem defeito","Duas rolinhas"],"c":1,"v":6,"e":"O versículo 6 manda trazer um carneiro sem defeito do rebanho e entregá-lo ao sacerdote."},
 {"t":"multipla","p":"Depois de trocar de roupa, para onde o sacerdote levava as cinzas do altar?","o":["Para dentro da tenda da congregação","Para o rio mais próximo","Para fora do acampamento, a um lugar limpo","Para a casa de Arão"],"c":2,"v":11,"e":"No versículo 11, o sacerdote veste outras roupas e leva as cinzas para fora do acampamento, a um lugar limpo."},
 {"t":"multipla","p":"Onde Arão e seus filhos deviam comer o restante da oferta de manjares?","o":["Na casa de cada sacerdote","Fora do acampamento","Ao pé do monte","No pátio da tenda da congregação"],"c":3,"v":16,"e":"O versículo 16 diz que o restante deve ser comido em lugar sagrado, no pátio da tenda da congregação."},
 {"t":"multipla","p":"Como era dividida a oferta de manjares contínua no dia da unção?","o":["Metade pela manhã e metade à tarde","Toda oferecida ao meio-dia","Um terço em cada refeição","Toda oferecida ao pôr do sol"],"c":0,"v":20,"e":"No versículo 20, metade da décima parte de um efa era oferecida pela manhã e a outra metade à tarde."},
 {"t":"cv","p":"A oferta de manjares do sacerdote era totalmente queimada e não se comia.","c":true,"v":23,"e":"O versículo 23 diz que toda a oferta de manjares do sacerdote será totalmente queimada e não se comerá."},
 {"t":"cv","p":"O vaso de barro em que se cozinhava a oferta pelo pecado devia ser lavado com água e guardado.","c":false,"v":28,"e":"Segundo o versículo 28, o vaso de barro era quebrado; só o vaso de bronze era esfregado e lavado com água."},
 {"t":"cv","p":"A oferta pelo pecado cujo sangue era levado à tenda da congregação para expiação no santuário podia ser comida pelos sacerdotes.","c":false,"v":30,"e":"O versículo 30 diz que essa oferta não seria consumida, mas queimada no fogo."}
]}

Levítico 25 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"O que o israelita não devia fazer no sétimo ano?","o":["Semear o campo e podar a vinha","Vender a sua casa","Oferecer sacrifícios","Viajar para fora da terra"],"c":0,"v":4,"e":"No versículo 4 o sétimo ano é de descanso para a terra: não se semeia o campo nem se poda a vinha."},
 {"t":"multipla","p":"Em que dia se tocava a trombeta que anunciava o jubileu?","o":["No Dia da Expiação","No primeiro dia do ano","No dia da Páscoa","No último dia do ano"],"c":0,"v":9,"e":"O versículo 9 manda tocar a trombeta no décimo dia do sétimo mês, no Dia da Expiação."},
 {"t":"multipla","p":"O que Deus promete para que haja comida durante o ano de descanso?","o":["Mandar maná do céu","Derramar bênção no sexto ano para colher por três anos","Permitir colher metade do campo","Dar comida a partir dos estrangeiros"],"c":1,"v":21,"e":"No versículo 21 Deus promete derramar a sua bênção no sexto ano, para colherem frutos por três anos."},
 {"t":"multipla","p":"Por que a terra não podia ser vendida para sempre?","o":["Porque pertencia aos levitas","Porque pertencia ao rei","Porque a terra é do Senhor","Porque estava dividida entre as tribos"],"c":2,"v":23,"e":"O versículo 23 diz que a terra não será vendida para sempre, pois ela é do Senhor."},
 {"t":"multipla","p":"Até quando se podia resgatar uma casa vendida em cidade murada?","o":["Até o Ano do Jubileu","Até sete anos depois","Até um ano depois da venda","A qualquer tempo"],"c":2,"v":29,"e":"O versículo 29 diz que a casa em cidade murada pode ser resgatada dentro de um ano após a venda."},
 {"t":"cv","p":"Era permitido cobrar juros de um irmão empobrecido se o empréstimo fosse de alimento.","c":false,"v":37,"e":"O versículo 37 proíbe emprestar dinheiro com juros e também oferecer alimento em busca de lucro."},
 {"t":"cv","p":"O israelita que empobrecesse e se vendesse a um irmão devia ser tratado como escravo.","c":false,"v":39,"e":"O versículo 39 manda não o tratar como escravo, e o versículo 40 diz que ele ficará como jornaleiro até o Jubileu."},
 {"t":"cv","p":"O israelita vendido a um estrangeiro podia ser resgatado pelo tio ou pelo filho do tio.","c":true,"v":49,"e":"O versículo 49 diz que o tio, o filho do tio ou outro parente pode resgatá-lo, ou ele mesmo, se tiver meios."}
]}

Levítico 3 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Como deve ser o animal de gado oferecido em sacrifício pacífico?","o":["Sem defeito","Com exatamente um ano de idade","Obrigatoriamente macho","Nascido dentro do acampamento"],"c":0,"v":1,"e":"O versículo 1 diz que o animal, macho ou fêmea, deve ser oferecido sem defeito diante do Senhor."},
 {"t":"multipla","p":"O que o ofertante faz antes de imolar o animal?","o":["Lava o animal com água","Coloca a mão sobre a cabeça da oferta","Entrega o animal a Moisés","Corta o pelo do animal"],"c":1,"v":2,"e":"O versículo 2 diz que ele coloca a mão sobre a cabeça da oferta e a imola à porta da tenda da congregação."},
 {"t":"multipla","p":"Quem asperge o sangue ao redor do altar?","o":["O próprio ofertante","Moisés","Os filhos de Arão, os sacerdotes","Os anciãos do povo"],"c":2,"v":2,"e":"O versículo 2 diz que os filhos de Arão, os sacerdotes, aspergem o sangue ao redor do altar."},
 {"t":"multipla","p":"Onde os filhos de Arão queimam a gordura do sacrifício pacífico de gado?","o":["Sobre uma pedra fora do acampamento","Em cima do holocausto, sobre a lenha acesa no altar","Dentro da tenda, diante da arca","Numa fogueira à porta da tenda"],"c":1,"v":5,"e":"O versículo 5 diz que eles a queimam sobre o altar, em cima do holocausto que está sobre a lenha acesa."},
 {"t":"multipla","p":"No sacrifício pacífico de gado miúdo, que parte é oferecida junto com a gordura das entranhas?","o":["A cabeça inteira","O couro","As quatro patas","A cauda inteira, cortada rente ao espinhaço"],"c":3,"v":9,"e":"O versículo 9 inclui na oferta queimada a cauda inteira, cortada rente ao espinhaço."},
 {"t":"cv","p":"O capítulo permite oferecer uma cabra como sacrifício pacífico.","c":true,"v":12,"e":"O versículo 12 diz que, se a oferta for uma cabra, ela será apresentada diante do Senhor."},
 {"t":"cv","p":"Segundo o capítulo, toda a gordura pertence aos sacerdotes.","c":false,"v":16,"e":"O versículo 16 diz que toda a gordura é do Senhor."},
 {"t":"cv","p":"A proibição de comer gordura e sangue vale só enquanto o povo estiver no deserto.","c":false,"v":17,"e":"O versículo 17 diz que é estatuto perpétuo para todas as gerações, em todas as moradas."}
]}

Levítico 14 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Para a purificação do leproso, o sacerdote mandava tomar duas aves vivas e limpas, um pau de cedro, um pedaço de carmesim e o quê?","o":["Um ramo de hissopo","Um ramo de oliveira","Uma folha de palmeira","Um ramo de murta"],"c":0,"v":4,"e":"O versículo 4 lista as duas aves, o pau de cedro, o carmesim e um ramo de hissopo."},
 {"t":"multipla","p":"Depois de aspergir sete vezes quem se purificava, o que o sacerdote fazia com a ave viva?","o":["Oferecia no altar","Soltava para o campo aberto","Entregava ao purificado","Guardava no acampamento"],"c":1,"v":7,"e":"O versículo 7 diz que o sacerdote declarava a pessoa limpa e soltava a ave viva para o campo aberto."},
 {"t":"multipla","p":"Depois de lavar as vestes, rapar o cabelo e se banhar, onde a pessoa devia ficar por sete dias?","o":["Na tenda da congregação","Fora do arraial","Fora da sua tenda","Na casa do sacerdote"],"c":2,"v":8,"e":"O versículo 8 diz que ela entrava no arraial, mas ficava fora da sua tenda por sete dias."},
 {"t":"multipla","p":"Onde o sacerdote colocava o sangue da oferta pela culpa?","o":["Na testa e nas duas mãos","Na cabeça, no peito e nos pés","Na orelha esquerda, na mão esquerda e no pé esquerdo","Na orelha direita, no polegar da mão direita e no polegar do pé direito"],"c":3,"v":14,"e":"O versículo 14 diz que o sangue ia na ponta da orelha direita, no polegar da mão direita e no polegar do pé direito."},
 {"t":"multipla","p":"Se a pessoa fosse pobre, o que podia trazer para a oferta pelo pecado e para o holocausto?","o":["Duas rolas ou dois pombinhos","Dois cabritos","Um bezerro","Apenas flor de farinha"],"c":0,"v":22,"e":"O versículo 22 diz que o pobre trazia duas rolas ou dois pombinhos, um para a oferta pelo pecado e outro para o holocausto."},
 {"t":"cv","p":"O sacerdote mandava esvaziar a casa antes de chegar, para que nada do que estava nela fosse contaminado.","c":true,"v":36,"e":"O versículo 36 diz que a casa era esvaziada antes da chegada do sacerdote para que nada nela fosse contaminado."},
 {"t":"cv","p":"As pedras com a praga eram removidas e guardadas em um lugar limpo dentro da cidade.","c":false,"v":40,"e":"O versículo 40 diz que as pedras eram lançadas fora da cidade, em um lugar imundo."},
 {"t":"cv","p":"Na purificação da casa, as duas aves eram mortas.","c":false,"v":53,"e":"O versículo 53 diz que a ave viva era solta para fora da cidade, para o campo aberto."}
]}

Levítico 21 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Por quais mortos o sacerdote pode se tornar impuro?","o":["Pelo pai, mãe, filho, filha e irmão","Por qualquer morto do seu povo","Por um homem principal do seu povo","Por nenhum morto, em nenhum caso"],"c":0,"v":2,"e":"O versículo 2 permite exceção para o parente mais próximo: mãe, pai, filho, filha e irmão."},
 {"t":"multipla","p":"O que os sacerdotes não devem cortar?","o":["As extremidades da barba","As unhas das mãos","A orla das vestes","O cabelo dos filhos"],"c":0,"v":5,"e":"O versículo 5 diz que eles não cortarão as extremidades da barba."},
 {"t":"multipla","p":"O que acontece com a filha de sacerdote que se prostitui?","o":["Será queimada com fogo","Será apedrejada","Será expulsa do acampamento","Oferecerá um sacrifício pela culpa"],"c":0,"v":9,"e":"O versículo 9 diz que ela profana a honra do pai e será queimada com fogo."},
 {"t":"multipla","p":"Com quem o sumo sacerdote deve se casar?","o":["Com uma virgem do seu povo","Com uma viúva","Com uma mulher repudiada","Com a filha de outro sacerdote"],"c":0,"v":14,"e":"O versículo 14 diz que ele tomará por mulher uma virgem do seu povo."},
 {"t":"multipla","p":"O que o descendente de Arão com defeito ainda pode fazer?","o":["Comer do pão do seu Deus","Entrar até o véu","Aproximar-se do altar","Oferecer as ofertas queimadas"],"c":0,"v":22,"e":"O versículo 22 diz que ele poderá comer do pão do seu Deus, das coisas santas e das santidades."},
 {"t":"cv","p":"O sumo sacerdote pode se contaminar pelo cadáver do pai ou da mãe.","c":false,"v":11,"e":"O versículo 11 diz que ele não se deixará contaminar nem por seu pai nem por sua mãe."},
 {"t":"cv","p":"O sacerdote com defeito não deve se aproximar do altar.","c":true,"v":23,"e":"O versículo 23 diz que ele não entrará até o véu nem se aproximará do altar."},
 {"t":"cv","p":"Moisés transmitiu essas palavras somente a Arão.","c":false,"v":24,"e":"O versículo 24 diz que Moisés falou a Arão, a seus filhos e a todos os filhos de Israel."}
]}

Levítico 15 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"A quem o Senhor falou no início do capítulo?","o":["A Moisés e a Arão","Somente a Moisés","A Arão e a seus filhos","A Moisés e a Josué"],"c":0,"v":1,"e":"O versículo 1 diz que o Senhor falou a Moisés e a Arão."},
 {"t":"multipla","p":"O que acontecia com o vaso de barro que tocasse em quem tinha fluxo?","o":["Era lavado com água","Era destruído","Ficava imundo só até à tarde","Era levado ao sacerdote"],"c":1,"v":12,"e":"O versículo 12 manda destruir o vaso de barro e lavar com água o vaso de madeira."},
 {"t":"multipla","p":"Depois que o homem ficava limpo do fluxo, o que ele devia fazer para sua purificação?","o":["Contar sete dias, lavar as vestes e banhar-se em águas correntes","Jejuar três dias diante da tenda","Raspar a cabeça e ser aspergido com sangue","Ficar fora do arraial até a lua nova"],"c":0,"v":13,"e":"O versículo 13 manda contar sete dias, lavar as vestes e banhar o corpo em águas correntes."},
 {"t":"multipla","p":"O que o sacerdote fazia com as duas aves trazidas no oitavo dia?","o":["Oferecia as duas em holocausto","Sacrificava uma e soltava a outra no campo","Oferecia uma para expiação do pecado e a outra para holocausto","Devolvia as aves a quem as trouxe"],"c":2,"v":15,"e":"O versículo 15 diz que uma era oferecida para expiação do pecado e a outra para holocausto."},
 {"t":"multipla","p":"Por quantos dias a mulher ficava separada durante a menstruação habitual?","o":["Três dias","Sete dias","Catorze dias","Quarenta dias"],"c":1,"v":19,"e":"O versículo 19 diz que ela ficava separada por sete dias."},
 {"t":"cv","p":"O homem que coabitasse com a mulher durante a menstruação ficava imundo só até à tarde.","c":false,"v":24,"e":"O versículo 24 diz que ele ficava imundo por sete dias, e não só até à tarde."},
 {"t":"cv","p":"A mulher com fluxo de sangue fora do tempo da menstruação era considerada imunda todos os dias desse fluxo.","c":true,"v":25,"e":"O versículo 25 diz que ela seria imunda todos os dias do seu fluxo, como nos dias da menstruação."},
 {"t":"cv","p":"Essas leis foram dadas para que os israelitas não morressem por contaminar o tabernáculo do Senhor que estava no meio deles.","c":true,"v":31,"e":"O versículo 31 explica que a separação das impurezas era para que não morressem ao contaminar o tabernáculo."}
]}

Levítico 22 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Quais descendentes de Arão não podiam comer das coisas santas até estarem limpos?","o":["Quem fosse leproso ou tivesse fluxo","Quem tivesse viajado para fora do arraial","Quem tivesse jejuado no dia anterior","Quem fosse o filho mais novo de Arão"],"c":0,"v":4,"e":"O versículo 4 proíbe de comer das coisas santas o descendente de Arão que for leproso ou tiver fluxo, até que esteja limpo."},
 {"t":"multipla","p":"Quem tocava algo imundo podia voltar a comer das coisas sagradas quando?","o":["Depois de sete dias","Depois de banhar o corpo, ao pôr do sol","Depois de oferecer um cordeiro","Na manhã seguinte"],"c":1,"v":7,"e":"Os versículos 6 e 7 dizem que ele devia banhar o corpo em água e, ao pôr do sol, seria purificado e poderia comer."},
 {"t":"multipla","p":"Quem, da casa do sacerdote, podia comer das coisas sagradas?","o":["O hóspede do sacerdote","O jornaleiro do sacerdote","O estrangeiro que morava com ele","O escravo comprado com o dinheiro do sacerdote"],"c":3,"v":11,"e":"O versículo 11 permite que o escravo comprado com o dinheiro do sacerdote coma do que ele oferece."},
 {"t":"multipla","p":"Quem comesse algo sagrado por ignorância devia acrescentar quanto ao devolver?","o":["O dobro do valor","Um décimo do valor","Um quinto do valor","Nada, apenas devolver o item"],"c":2,"v":14,"e":"O versículo 14 manda acrescentar um quinto do valor e dar ao sacerdote junto com o item sagrado."},
 {"t":"multipla","p":"Um novilho ou cordeiro desproporcionado podia ser oferecido de que forma?","o":["Em cumprimento de voto","Como oferta voluntária","Como holocausto diário","De nenhuma forma"],"c":1,"v":23,"e":"O versículo 23 permite oferecê-lo como oferta voluntária, mas diz que não seria aceito se fosse por voto."},
 {"t":"cv","p":"Os animais recebidos da mão do estrangeiro podiam ser oferecidos ao Senhor.","c":false,"v":25,"e":"O versículo 25 proíbe oferecer animais da mão do estrangeiro, pois estão defeituosos e não seriam aceitos."},
 {"t":"cv","p":"O filhote de boi, cordeiro ou cabra ficava sete dias com a mãe e só a partir do oitavo dia podia ser oferecido.","c":true,"v":27,"e":"O versículo 27 diz que o animal fica sete dias com a mãe e, a partir do oitavo dia, é aceito como oferta queimada."},
 {"t":"cv","p":"O sacrifício de louvor podia ser comido até o dia seguinte.","c":false,"v":30,"e":"O versículo 30 manda comê-lo no mesmo dia, sem deixar nada até a manhã."}
]}

Levítico 26 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Se o povo guardar os mandamentos, o que Deus promete dar no tempo apropriado?","o":["As chuvas","O maná","Um rei","Novas cidades"],"c":0,"v":4,"e":"No versículo 4, Deus promete dar as chuvas no tempo apropriado, e a terra produzirá suas colheitas."},
 {"t":"multipla","p":"De que terra o Senhor lembra ter tirado o povo, quebrando os timões do seu jugo?","o":["Babilônia","Egito","Moabe","Assíria"],"c":1,"v":13,"e":"No versículo 13, o Senhor diz que os tirou da terra do Egito para que não fossem seus escravos."},
 {"t":"multipla","p":"Como Deus diz que ficarão os céus e a terra de quem não o escutar?","o":["Os céus como fogo e a terra como pó","Os céus como pedra e a terra como areia","Os céus como ferro e a terra como bronze","Os céus como cinza e a terra como sal"],"c":2,"v":19,"e":"No versículo 19, Deus diz que fará os céus como ferro e a terra como bronze."},
 {"t":"multipla","p":"Quando Deus romper o sustento de pão, o que vai acontecer?","o":["O pão cairá do céu","Dez mulheres assarão o pão em um só forno","O povo comerá até se fartar","O pão será guardado no santuário"],"c":1,"v":26,"e":"No versículo 26, dez mulheres assarão o pão em um só forno, e o povo comerá sem se fartar."},
 {"t":"multipla","p":"Nas terras dos inimigos, o que fará fugir os que restarem do povo?","o":["O som de uma trombeta","O rugido de um leão","O barulho de um trovão","O som de uma folha movendo-se"],"c":3,"v":36,"e":"No versículo 36, Deus diz que o som de uma folha movendo-se os perseguirá e eles fugirão como quem foge da espada."},
 {"t":"cv","p":"Enquanto o povo estiver na terra dos inimigos, a terra desolada terá descanso e desfrutará dos seus sábados.","c":true,"v":34,"e":"O versículo 34 diz que a terra folgará nos seus sábados todos os dias da sua assolação."},
 {"t":"cv","p":"Deus diz que, quando o povo estiver na terra dos inimigos, vai rejeitá-lo e invalidar a sua aliança com ele.","c":false,"v":44,"e":"No versículo 44, Deus diz o contrário: não os rejeitará nem invalidará a sua aliança com eles."},
 {"t":"cv","p":"Esses estatutos, juízos e leis foram dados aos filhos de Israel no monte Sinai, pela mão de Moisés.","c":true,"v":46,"e":"O versículo 46 diz que o Senhor deu essas leis no monte Sinai, pela mão de Moisés."}
]}
